function uniqueFill(r, slot) {
  return `${r.subject} ${slot}을 초보 말로 한 번 더 적습니다. ${r.title} 숫자는 오늘 기준이며 다음 화면이 같으면 이야기가 두꺼워집니다. 한 번의 고점이나 시가는 종가·공시와 따로 표에 두면 읽기 쉽습니다.`;
}

function thicken(r) {
  const x = X[r.id];
  if (SUM[r.id] && r.summary.length < 90) r.summary = SUM[r.id];
  const parts = splitBody(r.body);
  const isSummary = !!(r.pinned || r.subject === "한장요약");
  if (x) {
    if (isSummary) {
      if (x.큰 && parts["오늘의 큰 그림"]) parts["오늘의 큰 그림"] += "\n\n" + x.큰;
      if (x.시사 && parts["투자 시사점"]) parts["투자 시사점"] += "\n\n" + x.시사;
    } else {
      if (x.무슨 && parts["무슨 일인가요"]) parts["무슨 일인가요"] += "\n\n" + x.무슨;
      if (x.조금 && parts["조금만 더 알려드리면"]) parts["조금만 더 알려드리면"] += "\n\n" + x.조금;
      if (x.장기 && parts["장기적으로 보면"]) parts["장기적으로 보면"] += "\n\n" + x.장기;
      if (x.시사 && parts["투자 시사점"]) parts["투자 시사점"] += "\n\n" + x.시사;
    }
  }
  if (!isSummary) {
    if (parts["무슨 일인가요"]) parts["무슨 일인가요"] += "\n\n" + uniqueFill(r, "무슨 일");
    if (parts["조금만 더 알려드리면"]) parts["조금만 더 알려드리면"] += "\n\n" + uniqueFill(r, "배경");
    if (parts["장기적으로 보면"]) parts["장기적으로 보면"] += "\n\n" + uniqueFill(r, "장기 칸");
    if (parts["투자 시사점"]) parts["투자 시사점"] += "\n\n" + uniqueFill(r, "다음 확인");
  } else {
    if (parts["오늘의 큰 그림"]) parts["오늘의 큰 그림"] += "\n\n" + uniqueFill(r, "한장 요약");
    if (parts["투자 시사점"]) parts["투자 시사점"] += "\n\n" + uniqueFill(r, "표");
  }
  r.body = joinBody(parts, isSummary);
  return r;
}

function padAll(arr) {
  for (const r of arr) thicken(r);
  return arr;
}

module.exports = { padAll };
